"""RoboPaint reference painting. All robot state comes from public cameras/proprioception."""
import sys,time,json,math,os
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
import numpy as np
from PIL import Image
R=Robot(); SPEC=R.spec(); QUAT=np.array([-3.98743083e-7,1.,-3.55532393e-7,-2.86572686e-8])
OUT='/app/output'
def execute(rows,note='',cams=None,frames=False):
    rows=np.asarray(rows,dtype=np.float32)
    results=[]
    for i in range(0,len(rows),180):
        chunk=rows[i:i+180]
        before=R.status()
        try:
            res=R.submit('ee_pose',chunk,dt=.05,cameras=cams or ['canvas_cam'],video='frames' if frames else 'none',video_fps=5,note=note)
        except Exception as e:
            print('CALL ERROR',str(e),flush=True)
            after=R.wait_ready(); print('RESUMED',after,flush=True)
            if after['calls']==before['calls']: res=R.submit('ee_pose',chunk,dt=.05,cameras=cams or ['canvas_cam'],video='none',note=note)
            else: res=R.get_obs(cameras=cams or ['canvas_cam'])
        results.append(res)
        if res.stopped: raise RuntimeError('Call stopped early')
        p=res.meta.get('plan',{})
        if p: print('PLAN',str(p)[:300],flush=True)
    return results[-1]
def current(): return np.array(R.get_obs(cameras=[]).meta['proprio']['now'][7:14])
def interpolate(a,b,speed=.12,hold=.2):
    n=max(1,int(np.ceil(np.linalg.norm(np.array(b[:3])-np.array(a[:3]))/speed/.05)))
    rows=[np.r_[np.array(a[:3])+(np.array(b[:3])-np.array(a[:3]))*t,QUAT] for t in np.linspace(1/n,1,n)]
    rows += [np.r_[b[:3],QUAT]]*int(hold/.05)
    return rows
def move(xyz,speed=.12,hold=.3,cams=None):
    return execute(interpolate(current(),np.r_[xyz,QUAT],speed,hold),'position brush',cams)
def saveobs(name,cams=None,depth=False):
    o=R.get_obs(cameras=cams or ['canvas_cam','scene_cam','side_cam'],depth=depth)
    for k,v in o.last.items(): Image.fromarray(v).save(f'{OUT}/{name}_{k}.png')
    for k,v in o.last_depth.items(): np.save(f'{OUT}/{name}_{k}_depth.npy',v)
    open(f'{OUT}/{name}_meta.json','w').write(json.dumps(o.meta,indent=2))
    return o
if __name__=='__main__':
    move([-.20,.20,.13])
    saveobs('uncovered',['canvas_cam','scene_cam','practice_cam'],True)
