def precise_execute(poses,note='',cams=None):
    q=R.get_obs(cameras=[]).meta['proprio']['now'][:7]
    poses=np.asarray(poses);actions=[]
    for pose in poses:
        sol=R.ik({'tip':pose.tolist()},seed=q,tol_pos_m=1e-5,tol_rot_rad=1e-4,max_iters=200)
        if not sol['ok']: raise RuntimeError('IK failed '+str(sol))
        q=sol['q'];actions.append(q)
    for i in range(0,len(actions),180):
        a=actions[i:i+180];before=R.status()
        try: res=R.submit('joint_position',a,dt=.05,cameras=cams or [],video='none',note=note)
        except Exception as e:
            print('ERROR',e,flush=True);after=R.wait_ready()
            if after['calls']==before['calls']:res=R.submit('joint_position',a,dt=.05,cameras=cams or [],video='none',note=note)
            else:res=R.get_obs(cameras=cams or [])
        if res.stopped:raise RuntimeError('Stopped joint call')
    return res

def precise_path(points,speed=.04,note='paint',cam=None):
    a=current();rows=[];p0=points[0];lift=max(.045,a[2])
    for p,s,h in [(list(a[:2])+[lift],.12,.1),([p0[0],p0[1],lift],.12,.15),(p0,.03,.3)]:
        b=np.r_[p,QUAT];rows+=interpolate(a,b,s,h);a=b
    for p in points[1:]:
        b=np.r_[p,QUAT];rows+=interpolate(a,b,speed,0);a=b
    rows += [a]*5;rows+=interpolate(a,np.r_[a[:2],.05,QUAT],.06,.3)
    return precise_execute(rows,note,[cam] if cam else [])
